  const willRemountByClearingQuery =
    String(this.$route.query?.[PERMIT_PLAN_NAV_RESTORE_QUERY]) === '1' ||
    String(this.$route.query?.restore) === '1'
  if (!willRemountByClearingQuery) {
    sessionStorage.removeItem(PERMIT_PLAN_NAV_DRAFT_KEY)
